<?= view('templates/header', ['pageTitle' => 'Task List']) ?>
<div class="mb-4"><p class="text-primary fw-semibold mb-1">Complete overview</p><h1 class="display-6 fw-bold mb-0">Task List</h1></div>
<?php if ($tasks === []): ?><div class="alert alert-info">No tasks exist in the database.</div><?php else: ?><div class="table-responsive bg-white rounded shadow-sm"><table class="table table-hover align-middle mb-0"><thead class="table-primary"><tr><th>ID</th><th>Title</th><th>Status</th><th>Task Date</th><th>Created Date</th></tr></thead><tbody><?php foreach ($tasks as $task): ?><?php $status = strtolower((string) $task['status']); $badge = $status === 'completed' ? 'success' : (($status === 'in progress' || $status === 'in_progress') ? 'warning text-dark' : 'secondary'); ?><tr><td><?= esc($task['id']) ?></td><td><?= esc($task['title']) ?></td><td><span class="badge bg-<?= esc($badge) ?>"><?= esc(ucwords(str_replace('_', ' ', $task['status']))) ?></span></td><td><?= esc($task['task_date']) ?></td><td><?= esc($task['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
